	private static EvaluationStrategy experimentalEvaluator(TripleSource tripleSource) {
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(tripleSource, null);
		strategy.setQueryExecutionPolicy(QueryExecutionPolicy.EXPERIMENTAL);
		return strategy;
	}

	/**
	 * Tests joins between two different BindingSetAssignments with the same BindingSets but ordered differently.
	 */
	@Test
	public void testBindingSetAssignmentJoin() throws QueryEvaluationException {
		testBindingSetAssignmentJoin(5, 5, EmptyBindingSet.getInstance());

		{
			QueryBindingSet b = new QueryBindingSet();
			b.addBinding("a", vf.createLiteral(2));
			testBindingSetAssignmentJoin(1, 5, b);
		}

		{
			QueryBindingSet b = new QueryBindingSet();
			b.addBinding("x", vf.createLiteral("foo"));
			testBindingSetAssignmentJoin(5, 5, b);
		}
	}

	@Test
	public void testBoundStatementPatternJoinUsesGuardAlgorithm() {
		CountingTripleSource tripleSource = new CountingTripleSource();
		EvaluationStrategy evaluator = experimentalEvaluator(tripleSource);
		BindingSetAssignment left = new BindingSetAssignment();
		List<BindingSet> rows = new ArrayList<>();
		for (int i = 0; i < 3; i++) {
			QueryBindingSet row = new QueryBindingSet();
			row.addBinding("s", tripleSource.statement.getSubject());
			row.addBinding("p", tripleSource.statement.getPredicate());
			row.addBinding("o", tripleSource.statement.getObject());
			rows.add(row);
		}
		left.setBindingSets(rows);

		Join join = new Join(left, new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o")));
		CloseableIteration<BindingSet> result = evaluator
				.precompile(join)
				.evaluate(EmptyBindingSet.getInstance());

		assertEquals("BoundStatementPatternJoinIteration", join.getAlgorithmName());
		assertEquals(3, Iterations.asList(result).size());
		assertEquals(1, tripleSource.countLookupCount);
		assertEquals(0, tripleSource.statementLookupCount);
	}

